head.script:
// ===== 리턴 값 출력 영역 =====
scwin.btn_clear_onclick = function (e) {
    $p.getComponentById("tbx_return").setValue("");
};

scwin.setReturnValue = function (strValue) {
    var objReturn = $p.getComponentById("tbx_return");
    objReturn.setValue(objReturn.getValue() + strValue);
    objReturn.setValue(objReturn.getValue() + "\n");
};

// ===== 결함 재현 (5.0 vs 6.0 동작 비교) =====
// 바인딩 대상 Key 의 값과 DatePicker 의 입력값을 함께 출력해 일치 여부를 본다
scwin.btn_check_onclick = function (e) {
    var objTarget = $p.getComponentById("target1");
    var objInfo = objTarget.getDataListInfo();

    scwin.setReturnValue("=====ref 바인딩 상태 확인=====");
    scwin.setReturnValue("getDataListInfo() : " + (objInfo === null ? "null" : "id='" + objInfo.id + "' / ref='" + objInfo.ref + "'"));
    scwin.setReturnValue("바인딩 대상 dm_ref.key1 값 : " + $p.getComponentById("dm_ref").get("key1"));
    scwin.setReturnValue("getValue() : " + objTarget.getValue());
};
